<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Your bag | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/commerce.css"></head>
<body><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/shop">Continue shopping</a><a href="/account">Account</a></nav></header><main class="commerce-shell"><div class="commerce-heading"><p class="eyebrow">Your selections</p><h1>Your bag</h1><p><?= count($items) ?> <?= count($items) === 1 ? 'piece' : 'pieces' ?>, ready when you are.</p></div><?php if ($error): ?><p class="auth-error"><?= htmlspecialchars($error) ?></p><?php endif; ?><?php if ($items): ?><div class="cart-layout"><section class="cart-items"><?php foreach ($items as $item): ?><article class="cart-item"><img loading="lazy" src="<?= htmlspecialchars($item['image']) ?>" alt="<?= htmlspecialchars($item['name']) ?>"><div><p class="eyebrow"><?= htmlspecialchars($item['vendor']) ?></p><h2><?= htmlspecialchars($item['name']) ?></h2><p>₹<?= number_format($item['price'], 0) ?> each</p><form method="post" action="/cart/update" class="quantity-form"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="product_id" value="<?= htmlspecialchars($item['product_id']) ?>"><input name="quantity" type="number" min="0" max="<?= htmlspecialchars($item['stock']) ?>" value="<?= htmlspecialchars($item['quantity']) ?>"><button type="submit">Update</button><span><?= $item['stock'] ?> available</span></form></div><strong>₹<?= number_format($item['line_total'], 0) ?></strong></article><?php endforeach; ?></section><aside class="order-summary"><p class="eyebrow">Summary</p><h2>Order total</h2><div><span>Subtotal</span><strong>₹<?= number_format($subtotal, 0) ?></strong></div><p>Shipping and taxes are confirmed at checkout.</p><a class="button" href="/checkout">Continue to checkout <span>→</span></a></aside></div><?php else: ?><div class="empty-commerce"><h2>Your bag is waiting.</h2><p>Explore the collection and bring something home.</p><a class="button" href="/shop">Browse the collection <span>→</span></a></div><?php endif; ?></main></body></html>